INSERT INTO transactions (pledge_id, project_id, type, amount, method, gateway_ref, status, created_at)
SELECT p.id, p.project_id, 'payment', p.amount, 'VNPay',
       'VNP-' || upper(substring(p.id::text, 1, 8)), 'success', p.created_at
  FROM pledges p
 WHERE p.status = 'paid';

